/** An SVG QR-style badge for a short link: the slug's bits as a 7×7 grid of squares. */
export function qrFor(slug: string): string {
  const bits = [...slug].flatMap((ch) => [...ch.charCodeAt(0).toString(2).padStart(7, "0")])
  const cells = bits
    .map((bit, i) => (bit === "1" ? `<rect x="${i % 7}" y="${Math.floor(i / 7)}" width="1" height="1"/>` : ""))
    .join("")
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 7 7">${cells}</svg>`
}
